function validate([values, labels, numWanted, useLimit]) {
  const n = values.length;
  if (n < 1 || n > 20000) return 'values needs 1 to 20000 items.';
  if (labels.length !== n) return 'values and labels must have the same length.';
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > 20000)) return 'Each value is between 0 and 20000.';
  if (labels.some(v => !Number.isInteger(v) || v < 0 || v > 20000)) return 'Each label is between 0 and 20000.';
  if (!Number.isInteger(numWanted) || numWanted < 1 || numWanted > n) return 'numWanted is between 1 and n.';
  if (!Number.isInteger(useLimit) || useLimit < 1 || useLimit > n) return 'useLimit is between 1 and n.';
  return null;
}

