function largestValsFromLabels(values, labels, numWanted, useLimit) {
  const order = values.map((_, i) => i);
  order.sort((a, b) => values[b] - values[a]);
  const used = new Map();
  let sum = 0;
  let taken = 0;
  for (const i of order) {
    if (taken === numWanted) break;
    const count = used.get(labels[i]) ?? 0;
    if (count === useLimit) continue;
    used.set(labels[i], count + 1);
    sum += values[i];
    taken++;
  }
  return sum;
}

