function largestValsFromLabels(values, labels, numWanted, useLimit) {
  // Try every subset that respects both caps by deciding item by item: skip it or take it.
  const n = values.length;
  const perLabel = {};
  let best = 0;
  const search = (index, chosen, total) => {
    if (total > best) best = total;
    if (index === n) return;
    search(index + 1, chosen, total);
    const label = labels[index];
    if (chosen < numWanted && (perLabel[label] || 0) < useLimit) {
      perLabel[label] = (perLabel[label] || 0) + 1;
      search(index + 1, chosen + 1, total + values[index]);
      perLabel[label]--;
    }
  };
  search(0, 0, 0);
  return best;
}

