function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const labelCount = [5, 60, 20001][int(0, 2)];
    const values = Array.from({ length: n }, () => int(0, 20000));
    const labels = Array.from({ length: n }, () => int(0, labelCount - 1));
    return [values, labels, int(1, n), int(1, rand() < 0.7 ? 40 : n)];
  }
  const n = int(1, 10);
  const top = rand() < 0.3 ? 20000 : 12;
  const labelCount = int(1, 4);
  const values = Array.from({ length: n }, () => int(0, top));
  const labels = Array.from({ length: n }, () => int(0, labelCount - 1) * (rand() < 0.2 ? 5000 : 1));
  return [values, labels, int(1, n), int(1, n)];
}
